using System;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using IdleRestaurant;
public static class CleanupModelChecks{
 public static object Main(){var c=AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(RestaurantProductionBuilder.CatalogPath);var checks=new List<string>();Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception(name);checks.Add(name);};var g=new RestaurantGame(c);double now=1000;g.Now=()=>now;g.State.introComplete=true;g.State.guideStep=6;check(!g.RequestCleanup(0)&&g.State.cash==0,"Empty cleanup cannot award money");var a=new ServiceGuest{id=0,seat=0,mealPaid=true};g.LeaveDirtyPlate(0,a);g.LeaveDirtyPlate(0,a);check(g.MessCount(0)==1&&g.State.outlets[0].dirt[0].count==1,"A finished meal creates one dirty dish only once");g.LeaveDirtyPlate(0,new ServiceGuest{id=1,seat=1,mealPaid=true});check(g.MessCount(0)==1&&g.State.outlets[0].dirt[0].count==2,"Used dishes stack at a shared table edge");g.State.outlets[0].dirt.Add(new CleanupMess{id=++g.State.cleanupSequence,kind=1,x=0,z=-2.15f});g.State.outlets[0].dirt.Add(new CleanupMess{id=++g.State.cleanupSequence,kind=2,x=.35f,z=-.15f});double income=g.NetworkIncome(),expected=income*1.5;int[] ids=g.State.outlets[0].dirt.Select(m=>m.id).ToArray();check(g.RequestCleanup(0)&&g.State.cleanupJob.active,"Tap requests a janitor visit");check(g.State.cleanupJob.messIds.OrderBy(x=>x).SequenceEqual(ids.OrderBy(x=>x)),"One visit includes all dirt present when called");check(Math.Abs(g.State.cleanupJob.reward-expected)<1e-8,"Reward is exactly 1.5 times displayed base income/min at dispatch");int visitId=g.State.cleanupJob.id;check(!g.RequestCleanup(0)&&g.State.cleanupJob.id==visitId&&g.State.cash==0,"Repeated taps during a visit cannot duplicate jobs or rewards");for(int i=0;i<20;i++){now+=.05;g.Tick(.05);}var payload=Newtonsoft.Json.JsonConvert.SerializeObject(g.State);var restored=new RestaurantGame(c,Newtonsoft.Json.JsonConvert.DeserializeObject<SaveState>(payload));restored.Now=()=>now;check(restored.State.cleanupJob.active&&restored.State.cleanupJob.id==visitId&&restored.State.cleanupJob.messIds.SequenceEqual(ids)&&Math.Abs(restored.State.cleanupJob.reward-expected)<1e-8,"An active janitor visit and fixed payout survive save/load");g=restored;int paid=0;g.CleanupPaid=(o,v)=>{paid++;check(o==0&&Math.Abs(v-expected)<1e-8,"Completion callback pays the promised amount");};for(int i=0;i<3000&&g.State.cleanupJob.active;i++){now+=.05;g.Tick(.05);}check(!g.State.cleanupJob.active&&g.State.cleanupJob.paid&&paid==1,"Janitor finishes and pays once");check(ids.All(id=>!g.State.outlets[0].dirt.Any(m=>m.id==id)),"Every item in the dispatched batch is cleaned");check(Math.Abs(g.State.cash-expected)<1e-7&&Math.Abs(g.State.totalEarned-expected)<1e-7,"Cash ledger credits exactly one cleanup reward");check(g.State.outlets[0].waveIncome==0&&Math.Abs(g.NetworkIncome()-income)<1e-7,"Cleanup bonus does not inflate service income, completion bonuses or income/min");for(int i=0;i<40;i++){now+=.05;g.Tick(.05);}check(paid==1&&g.State.cleanupVisits==1,"Further ticks do not pay the completed visit again");g.State.outlets[0].dirt.Add(new CleanupMess{id=++g.State.cleanupSequence,kind=1,x=0,z=-2.15f});check(g.RequestCleanup(0)&&!g.State.cleanupJob.active&&g.State.queuedCleanup==0,"A cooldown tap queues one later visit");double ready=g.State.cleanupReadyUtc;now=ready-.1;g.Tick(.05);check(!g.State.cleanupJob.active,"Queued janitor does not dispatch before the 90-second reward interval");now=ready+.1;g.Tick(.05);check(g.State.cleanupJob.active&&g.State.cleanupJob.id!=visitId&&g.State.cleanupVisits==1,"Queued janitor dispatches when the confirmed interval expires");check(g.State.outlets[0].dirt.Count(m=>m.kind!=0)<=c.familyBalance.maxFloorLitter+1,"Ambient floor dirt stays bounded");
 var old=Newtonsoft.Json.Linq.JObject.Parse(payload);old.Remove("cleanupJob");old.Remove("cleanupSequence");old.Remove("cleanupReadyUtc");foreach(var o in (Newtonsoft.Json.Linq.JArray)old["outlets"]){((Newtonsoft.Json.Linq.JObject)o).Remove("dirt");((Newtonsoft.Json.Linq.JObject)o).Remove("nextLitterSeconds");}var legacy=new RestaurantGame(c,old.ToObject<SaveState>());check(legacy.State.cleanupJob!=null&&legacy.State.outlets.All(o=>o.dirt!=null)&&legacy.MessCount(0)==0,"Existing saves without cleanup fields load safely");check(c.guestVariants.Length==12&&c.guestVariants.Count(p=>p.GetComponent<RestaurantCharacterAppearance>().feminine)==6,"Twelve editable guest looks include six feminine and six masculine presentations");check(c.guestVariants.All(p=>p.GetComponent<RestaurantActorRig>().leftKnee&&p.GetComponent<RestaurantActorRig>().rightKnee),"All varied guests have articulated knees");check(c.chefVariants.Count(p=>p.GetComponent<RestaurantCharacterAppearance>().feminine)==3&&c.hostVariants.Count(p=>p.GetComponent<RestaurantCharacterAppearance>().feminine)==3,"Chefs and hosts also have balanced appearance variety");check(c.janitorVariants.Length==2&&c.janitorVariants.Select(p=>p.GetComponent<RestaurantCharacterAppearance>().feminine).Distinct().Count()==2,"Janitor visits can use two different gender presentations");var result=new{utc=DateTime.UtcNow,status="PASS",checks,scope="Isolated seeded models and authored prefab inspection; live gameplay checks are separate",rewardMinutes=c.familyBalance.cleanupRewardMinutes,repeatSeconds=c.familyBalance.cleanupRewardIntervalSeconds};File.WriteAllText("/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/CleanupModelChecks.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return new{status="PASS",checks=checks.Count};}
}
